//! Cloudflare Tunnel: cloudflared's ingress rules.

use super::{Out, url};
use crate::proxy::{Plan, ProxySettings};

pub(super) fn cloudflared(on: &[&Plan], _s: &ProxySettings, _lan: &[String]) -> Out {
    let mut public = on.to_vec();
    public.sort_by(|a, b| (&a.fqdn, a.path.is_empty()).cmp(&(&b.fqdn, b.path.is_empty())));
    let mut l: Vec<String> = [
        "# cloudflared config.yml: generated by wranglarr (wranglarr → Reverse proxy).",
        "# Create the tunnel and its DNS names first: cloudflared tunnel create, cloudflared tunnel route dns.",
        "tunnel: <your tunnel id>",
        "credentials-file: /etc/cloudflared/<your tunnel id>.json",
        "ingress:",
    ]
    .map(String::from)
    .to_vec();
    for p in public {
        l.push(format!("  # {}", p.name));
        l.push(format!("  - hostname: {}", p.fqdn));
        if !p.path.is_empty() {
            l.push(format!("    path: ^{}(/|$)", regex::escape(&p.path)));
        }
        l.push(format!("    service: {}", url(&p.up)));
        if p.sab {
            l.push("    originRequest:".into());
            l.push(format!("      httpHostHeader: \"{}\"", p.up));
        }
    }
    l.push("  - service: http_status:404".into());
    l.push(String::new());
    (l.join("\n"), "config.yml", "Merge into cloudflared's config.yml and restart cloudflared.")
}
